import json, collections, os
from pathlib import Path

# Sample many session files to find any unseen 'type' values, attachment hook names, content-block types, sidechain prevalence
session_files = sorted(Path(".").glob("*.jsonl"))
print(f"sessions: {len(session_files)}")

all_types = collections.Counter()
attachment_hooks = collections.Counter()
content_block_types = collections.Counter()
sidechain_counts = collections.Counter()
models = collections.Counter()
stop_reasons = collections.Counter()
usage_keys = set()
user_content_kinds = collections.Counter()
tool_names = collections.Counter()

for sf in session_files[:8]:  # cap
    try:
        for line in sf.open():
            if not line.strip(): continue
            obj = json.loads(line)
            t = obj.get("type","?")
            all_types[t] += 1
            sidechain_counts[(t, obj.get("isSidechain"))] += 1
            if t == "attachment":
                a = obj.get("attachment", {})
                if isinstance(a, dict):
                    attachment_hooks[(a.get("hookEvent"), a.get("hookName"))] += 1
            if t == "assistant":
                msg = obj.get("message", {})
                models[msg.get("model")] += 1
                stop_reasons[msg.get("stop_reason")] += 1
                u = msg.get("usage", {})
                if isinstance(u, dict): usage_keys.update(u.keys())
                for b in msg.get("content", []):
                    if isinstance(b, dict):
                        bt = b.get("type")
                        content_block_types[("assistant", bt)] += 1
                        if bt == "tool_use":
                            tool_names[b.get("name")] += 1
            if t == "user":
                msg = obj.get("message", {})
                content = msg.get("content")
                if isinstance(content, str):
                    user_content_kinds["string"] += 1
                elif isinstance(content, list):
                    for b in content:
                        if isinstance(b, dict):
                            content_block_types[("user", b.get("type"))] += 1
                            user_content_kinds[f"list[{b.get('type')}]"] += 1
    except Exception as e:
        print(f"err {sf}: {e}")

print("\n=== line types (8 sessions) ===")
for t,c in all_types.most_common(): print(f"  {t:30} {c}")
print("\n=== attachment (hookEvent, hookName) ===")
for k,c in attachment_hooks.most_common(20): print(f"  {k} {c}")
print("\n=== content block types ===")
for k,c in content_block_types.most_common(): print(f"  {k} {c}")
print("\n=== sidechain by type ===")
for k,c in sidechain_counts.most_common(): print(f"  {k}: {c}")
print("\n=== models ===")
for k,c in models.most_common(): print(f"  {k}: {c}")
print("\n=== stop_reasons ===")
for k,c in stop_reasons.most_common(): print(f"  {k}: {c}")
print("\n=== usage keys union ===")
print(" ", sorted(usage_keys))
print("\n=== user content kinds ===")
for k,c in user_content_kinds.most_common(): print(f"  {k}: {c}")
print("\n=== top tools ===")
for k,c in tool_names.most_common(15): print(f"  {k}: {c}")

# Inspect the subagents and tool-results directories
print("\n=== one session's subagents/ ===")
sdir = Path("0b4e92d3-b10f-47c7-a4f2-154a946e9f18/subagents")
if sdir.exists():
    items = list(sdir.iterdir())[:6]
    for p in items:
        print(" ", p.name, "size=", p.stat().st_size if p.is_file() else "(dir)")
    if items and items[0].is_file():
        sample = json.loads(items[0].read_text().splitlines()[0]) if items[0].suffix == ".jsonl" else None
        if sample:
            print("  first line keys:", sorted(sample.keys()))
            print("  type:", sample.get("type"), "isSidechain:", sample.get("isSidechain"))

print("\n=== one session's tool-results/ ===")
trdir = Path("0b4e92d3-b10f-47c7-a4f2-154a946e9f18/tool-results")
if trdir.exists():
    for p in list(trdir.iterdir())[:6]:
        print(" ", p.name, "size=", p.stat().st_size if p.is_file() else "(dir)")
